func (a *HTTPAdapter) fail(w http.ResponseWriter, r *http.Request, err *httpserver.HandlerError) {
	// A response that failed to write leaves its media type, which is not the error's.
	w.Header().Del("Content-Type")
	a.opts.ErrorHandler.HandleError(w, r, err.StatusCode(), err)
}

func (a *HTTPAdapter) failDecode(w http.ResponseWriter, r *http.Request, id string, err error) {
	a.fail(w, r, &httpserver.HandlerError{Kind: httpserver.ErrorDecode, OperationID: id, Err: err})
}

func (a *HTTPAdapter) write(w http.ResponseWriter, r *http.Request, id string, res responseData) {
	if res.ContentType() != "" {
		w.Header().Set("Content-Type", res.ContentType())
	}
	err := httpserver.Write(w, res.StatusCode(), res.Header(), res.Payload())
	switch {
	case errors.Is(err, runtime.ErrContentType):
		a.fail(w, r, &httpserver.HandlerError{Kind: httpserver.ErrorResponse, OperationID: id, Err: err})
	case err != nil:
		a.fail(w, r, &httpserver.HandlerError{Kind: httpserver.ErrorService, OperationID: id, Err: err})
	}
}

// WithRouter registers the routes on r instead of a new Router.
func WithRouter(r *router.Router) ServerOption {
	return func(o *ServerOptions) {
		o.Router = r
	}
}

// NewRouter registers every operation on a fasthttp router.
func NewRouter(svc ServiceInterface, opts ...ServerOption) *router.Router {
	o := NewServerOptions(opts...)
	a := NewHTTPAdapter(svc, opts...)
	wrap := func(h http.Handler) http.Handler {
		for i := len(o.Middleware) - 1; i >= 0; i-- {
			h = o.Middleware[i](h)
		}
		// fasthttp would end the process on a panic.
		return httpserver.Recover(h, o.ErrorHandler)
	}
	register := func(r *router.Router, route func(http.Handler) http.Handler) {
		r.GET("/v1/{name}", handle(route(http.HandlerFunc(a.GetName))))
		r.DELETE("/v1/{name}", handle(route(http.HandlerFunc(a.DeleteName))))
		r.TRACE("/v1/{name}", handle(route(http.HandlerFunc(a.TraceName))))
		r.GET("/v1/{id}/children", handle(route(http.HandlerFunc(a.GetChildren))))
		r.PUT("/v1/:batch", handle(route(http.HandlerFunc(a.PutBatch))))
		r.GET("/geo/{lat_lng}", handle(route(http.HandlerFunc(a.GetGeo))))
		r.GET("/files/{name}\\.{ext}", handle(route(http.HandlerFunc(a.GetFile))))
		r.GET("/products({id}\\)", handle(route(http.HandlerFunc(a.GetProduct))))
		r.GET("/$metadata", handle(route(http.HandlerFunc(a.GetMetadata))))
		r.GET("/a:b", handle(route(http.HandlerFunc(a.GetColon))))
	}

	if r, _ := o.Router.(*router.Router); r != nil {
		register(r, wrap)
		return r
	}
	r := router.New()
	// The router would answer OPTIONS itself, past the middleware.
	r.HandleOPTIONS = false
	register(r, wrap)
	r.NotFound = handle(wrap(http.NotFoundHandler()))
	r.MethodNotAllowed = handle(wrap(http.HandlerFunc(methodNotAllowed)))
	return r
}

func handle(h http.Handler) fasthttp.RequestHandler {
	return func(ctx *fasthttp.RequestCtx) {
		fasthttpadaptor.NewFastHTTPHandler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			// fasthttp reuses the memory of the request's strings for the next request.
			r = httpserver.DetachRequest(r)
			ctx.VisitUserValues(func(key []byte, value any) {
				if s, ok := value.(string); ok {
					r.SetPathValue(string(key), httpserver.DetachPathValue(s))
				}
			})
			h.ServeHTTP(w, r)
		}))(ctx)
	}
}

func methodNotAllowed(w http.ResponseWriter, _ *http.Request) {
	w.WriteHeader(http.StatusMethodNotAllowed)
}
